INSERT INTO `points` (`id`, `language_id`, `icon`, `color`, `title`, `short_text`, `serial_number`) VALUES
(16, 170, 'fas fa-bullseye', '39498a', 'Objetivos', 'Um ótimo conselho financeiro começa com a compreensão de seus objetivos pessoais, financeiros e de estilo de vida Na Spring, ajudamos você.', 1),
(17, 170, 'fas fa-clipboard-list', '39498a', 'Planos', 'Objetivos sem um plano são apenas um sonho - portanto, na Primavera, nossa equipe de especialistas do setor trabalhará para desenvolver planos.', 2),
(18, 170, 'fas fa-sync', '39498a', 'Ações', 'Os planos exigem ação ou são apenas palavras - na Primavera, trabalhamos com você para implementar seus planos estratégicos.', 3),
(19, 169, 'fas fa-bullseye', '39498A', 'Goals', 'Great financial advice starts with an understanding of your personal, financial and lifestyle goals At Spring we help you.Great financial advice starts with an understanding of your personal, financial and lifestyle goals At Spring we help you.Great financial advice starts with an understanding of your personal, financial and lifestyle goals At Spring we help you.', 1),
(20, 169, 'fas fa-clipboard-list', 'F77272', 'Plans', 'Goals without a plan are just a dream– so at Spring our team of industry experts will work with you to develop strategic plans.', 2),
(22, 169, 'fas fa-sync', '69A66C', 'Actions', 'Plans require action or they are just words – at Spring we work with you to implement your strategic plans.', 3),
(23, 171, 'fas fa-bullseye', '39498a', 'Metas', 'Lorem ipsum dolor sit amet consectetur, adipisicing elit. Corrupti autem beatae eos unde sint provident minima.', 1),
(24, 171, 'fas fa-clipboard-list', '39498a', 'Planos', 'Lorem ipsum dolor sit amet consectetur, adipisicing elit. Corrupti autem beatae eos unde sint provident minima.', 2),
(25, 171, 'fas fa-sync', '39498a', 'Ações', 'Lorem ipsum dolor sit amet consectetur, adipisicing elit. Corrupti autem beatae eos unde sint provident minima.', 3),
(26, 173, 'fas fa-bullseye', '39498a', 'الأهداف', 'تبدأ المشورة المالية العظيمة بفهم أهدافك الشخصية والمالية وأسلوب حياتك في الربيع نساعدك.', 1),
